路！</p>\n\n                    <blockquote>\n                    <h3>🧠 幻银超i（HYQi）的愿景</h3>\n\n                    <p>我们正以实时的真实交易环境去训练Ai，以此来测试并提高Ai的智慧，运用开放式学习、大规模强化学习等技术来驾驭其复杂性。</p>\n\n                    <p>心怀此念，我们正广纳贤才，招募资深ai研究员、创业伙伴与思维破局者。</p>\n\n                    <p>如果您渴望为现实世界打造Alpha-HYQi，欢迎与我们携手。简历请发送至：hyqi@tradey.dpdns.org</p>\n\n                    <p>\"资本配置，是ai智慧接受真理检验的最佳试金石\"。</p>\n\n                    <p>———幻银超i与您共勉</p>\n                    </blockquote>\n                </div>\n            </div>\n            \n            <div class=\"right-column\">\n                <div class=\"logs-container\">\n                    <div class=\"logs-header\">\n                        <h2>运行日志</h2>\n                        <button id=\"loadMoreLogsBtn\">加载更多历史</button>\n                    </div>\n                    <div id=\"logContainer\"></div>\n                </div>\n            </div>\n        </div>\n    </div>\n\n    <script>\n        // 从配置获取 API 地址\n        // 注意：Tailscale Funnel URL 格式通常是 https://xxx.ts.net（已包含端口映射）\n        const API_BASE = window.API_CONFIG ? window.API_CONFIG.baseUrl : 'http://localhost:4000';\n        \n        // Socket.IO 服务器地址\n        // Tailscale Funnel 通过 HTTPS 暴露 4000 端口，Socket.IO 会自动使用 WSS（WebSocket Secure）\n        let SOCKET_URL = API_BASE;\n        const LOG_LIMIT=(window.API_CONFIG&&window.API_CONFIG.logLimit!==undefined)?Number(window.API_CONFIG.logLimit):null;\n        const LOG_PAGE_SIZE=(window.API_CONFIG&&window.API_CONFIG.logPageSize)||100;\n        const LOG_KEY_SET=new Set();\n        const logPagination={nextCursor:null,hasMore:true,loading:false};\n        let logContainerRef=null;\n        let loadMoreLogsBtn=null;\n        if (!SOCKET_URL.startsWith('http')) {\n            // 如果 URL 没有协议，添加 http://\n            SOCKET_URL = `http://${SOCKET_URL}`;\n        }\n        \n        // 检查是否是 Tailscale Funnel URL（.ts.net 域名）\n        const isTailscaleFunnel = SOCKET_URL.includes('.ts.net');\n        const isLocalhost = SOCKET_URL.includes('localhost') || SOCKET_URL.includes('127.0.0.1');\n        \n        console.log('🔧 API 配置:', {\n            API_BASE: API_BASE,\n            SOCKET_URL: SOCKET_URL,\n            isTailscaleFunnel: isTailscaleFunnel,\n            isLocalhost: isLocalhost\n        });\n        \n        // 初始化SocketIO连接（如果可用）\n        // Tailscale Funnel 支持 WebSocket，可以实现实时推送\n        let socket = null;\n        let useSocketIO = false;\n        let chart = null;\n        const RECENT_CHART_POINTS = 50;\n        let showFullData = false;\n        let lastPerformanceData = null;\n        function chartPointStyle() {\n            const pointR = showFullData ? 0 : 4;\n            return {\n                borderWidth: 1,\n                borderCapStyle: 'butt',\n                borderJoinStyle: 'miter',\n                tension: showFullData ? 0 : 0.4,\n                pointRadius: pointR,\n                radius: pointR,\n                pointHoverRadius: showFullData ? 4 : 6,\n                pointHitRadius: 16\n            };\n        }\n        function applyChartJsLineDefaults() {\n            if (typeof Chart === 'undefined' || !Chart.defaults) return;\n            if (Chart.defaults.elements && Chart.defaults.elements.line) {\n                Chart.defaults.elements.line.borderWidth = 1;\n                Chart.defaults.elements.line.borderCapStyle = 'butt';\n                Chart.defaults.elements.line.borderJoinStyle = 'miter';\n            }\n            if (Chart.defaults.datasets && Chart.defaults.datasets.line) {\n                Chart.defaults.datasets.line.borderWidth = 1;\n                Chart.defaults.datasets.line.borderCapStyle = 'butt';\n                Chart.defaults.datasets.line.borderJoinStyle = 'miter';\n            }\n        }\n        function syncChartElementStyle(targetChart) {\n            const style = chartPointStyle();\n            if (targetChart && targetChart.options) {\n                if (targetChart.options.elements && targetChart.options.elements.line) {\n                    targetChart.options.elements.line.borderWidth = 1;\n                    targetChart.options.elements.line.borderCapStyle = 'butt';\n                    targetChart.options.elements.line.borderJoinStyle = 'miter';\n                    targetChart.options.elements.line.tension = style.tension;\n                }\n                if (targetChart.options.elements && targetChart.options.elements.point) {\n                    targetChart.options.elements.point.radius = style.pointRadius;\n                    targetChart.options.elements.point.hoverRadius = style.pointHoverRadius;\n                    targetChart.options.elements.point.hitRadius = style.pointHitRadius;\n                }\n                if (!targetChart.options.datasets) targetChart.options.datasets = {};\n                if (!targetChart.options.datasets.line) targetChart.options.datasets.line = {};\n                targetChart.options.datasets.line.borderWidth = 1;\n                targetChart.options.datasets.line.borderCapStyle = 'butt';\n                targetChart.options.datasets.line.borderJoinStyle = 'miter';\n            }\n            return style;\n        }\n        function isLiveChartPoint(point) {\n            if (!point || typeof point !== 'object') return false;\n            if (point.source === 'live') return true;\n            if (point.source === 'history') return false;\n            return point.cycle == null && point.total_equity == null;\n        }\n        function filterLiveChartData(data) {\n            const result = {};\n            for (const [name, points] of Object.entries(data || {})) {\n                if (!Array.isArray(points)) {\n                    result[name] = points;\n                    continue;\n                }\n                result[name] = points.filter(isLiveChartPoint);\n            }\n            return result;\n        }\n        function chartTimeKey(value) {\n            return value == null ? '' : String(value);\n        }\n        function mergePerformanceData(existing, incoming) {\n            if (!existing) return incoming;\n            if (!incoming) return existing;\n            const merged = {};\n            const names = new Set([].concat(Object.keys(existing), Object.keys(incoming)));\n            names.forEach(function(name) {\n                const oldPts = Array.isArray(existing[name]) ? existing[name] : [];\n                const newPts = Array.isArray(incoming[name]) ? incoming[name] : [];\n                const byTime = {};\n                oldPts.concat(newPts).forEach(function(point) {\n                    if (!point || point.time == null) return;\n                    byTime[chartTimeKey(point.time)] = point;\n                });\n                merged[name] = Object.keys(byTime).sort().map(function(key) { return byTime[key]; });\n            });\n            return merged;\n        }\n        \n        try {\n            // Socket.IO 库可用且不是本地地址时，尝试连接\n            if (typeof io !== 'undefined' && !isLocalhost) {\n                console.log('🚀 尝试连接 Socket.IO 服务器:', SOCKET_URL);\n                \n                socket = io(SOCKET_URL, {\n                    reconnection: true,\n                    reconnectionDelay: 1000,\n                    reconnectionDelayMax: 5000,\n                    reconnectionAttempts: 10, // Tailscale 可能需要更多重试\n                    transports: ['websocket', 'polling'], // 优先 WebSocket，失败时降级到 polling\n                    timeout: 10000, // Tailscale 可能需要更长的超时\n                    autoConnect: true,\n                    forceNew: false,\n                    // 对于 HTTPS/WSS，确保正确处理证书\n                    rejectUnauthorized: false // Tailscale 使用自签名证书时需要\n                });\n                \n                // 连接成功\n                socket.on('connect', () => {\n                    useSocketIO = true;\n                    console.log('✅ Socket.IO 连接成功！');\n                    console.log('   - 服务器地址:', SOCKET_URL);\n                    console.log('   - 传输方式:', socket.io.engine.transport.name);\n                    console.log('   - 使用实时推送模式');\n                });\n                \n                // 连接失败\n                socket.on('connect_error', (error) => {\n                    useSocketIO = false;\n                    console.warn('⚠️ Socket.IO 连接失败，降级到 HTTP 轮询模式');\n                    console.warn('   错误信息:', error.message);\n                    console.warn('   将继续使用 HTTP 轮询获取数据');\n                });\n                \n                // 断开连接\n                socket.on('disconnect', (reason) => {\n                    useSocketIO = false;\n                    console.warn('⚠️ Socket.IO 断开连接:', reason);\n                    console.warn('   将切换到 HTTP 轮询模式');\n                });\n                \n                // 接收服务器确认\n                socket.on('connection_success', (data) => {\n                    console.log('✅ 服务器确认连接:', data);\n                });\n                \n                // 接收性能数据更新\n                socket.on('performance_update', (data) => {\n                    if (chart) {\n                        applyPerformanceChart(chart, data);\n                    }\n                });\n                \n                // 接收日志更新（实时推送）\n                socket.on('new_log', (data) => {\n                    const logContainer = document.getElementById('logContainer');\n                    if (logContainer) {\n                        addLogEntry(logContainer, data);\n                        // 重置轮询计数器（如果SocketIO正常，就不需要轮询）\n                        if (typeof lastLogPollTime !== 'undefined') {\n                            lastLogPollTime = Date.now();\n                        }\n                    }\n                });\n            } else if (isLocalhost) {\n                console.log('ℹ️ 检测到本地地址，Socket.IO 将连接到本地服务器');\n                // 本地环境也尝试连接\n                socket = io(SOCKET_URL, {\n                    reconnection: true,\n                    transports: ['websocket', 'polling']\n                });\n                socket.on('connect', () => {\n                    useSocketIO = true;\n                    console.log('✅ 本地 Socket.IO 连接成功');\n                });\n                socket.on('connect_error', () => {\n                    useSocketIO = false;\n                    console.warn('⚠️ 本地 Socket.IO 连接失败，使用 HTTP 轮询');\n                });\n            } else {\n                console.log('ℹ️ Socket.IO 库未加载，使用 HTTP 轮询模式');\n            }\n        } catch (e) {\n            console.warn('⚠️ Socket.IO 初始化失败，使用 HTTP 轮询模式:', e.message);\n        }\n        \n        // 等待Chart.js加载完成后再初始化图表\n        function initChart() {\n            if (typeof Chart === 'undefined') {\n                console.log('Chart.js未加载完成，等待中...');\n                setTimeout(initChart, 1000);\n                return;\n            }\n            \n            applyChartJsLineDefaults();\n            console.log('Chart.js已加载，初始化图表');\n            \n            // 初始化图表\n            const ctx = document.getElementById('performanceChart').getContext('2d');\n            const chart = new Chart(ctx, {\n                type: 'line',\n                data: {\n                    labels: [],\n                    datasets: []\n                },\n                options: {\n                    responsive: true,\n                    maintainAspectRatio: false,\n                    interaction: {\n                        mode: 'nearest',\n                        intersect: false\n                    },\n                    scales: {\n                        x: {\n                            display: true,\n                            title: {\n                                display: true,\n                                text: '时间',\n                                font: {\n                                    size: 12\n                                }\n                            }\n                        },\n                        y: {\n                            display: true,\n                            title: {\n                                display: true,\n                                text: '累计收益率 (%)',\n                                font: {\n                                    size: 12\n                                }\n                            },\n                            ticks: {\n                                precision: 2,\n                                callback: function(value) {\n                                    return value.toFixed(2) + '%';\n                                }\n                            },\n                            beginAtZero: false,\n                            grace: '10%'\n                        }\n                    },\n                    animation: {\n                        duration: 500\n                    },\n                    plugins: {\n                        title: {\n                            display: true,\n                            text: 'AI模型收益率对比',\n                            font: {\n                                size: 14,\n                                weight: 'bold'\n                            }\n                        },\n                        legend: {\n                            position: 'top',\n                        }\n                    },\n                    datasets: {\n                        line: {\n                            borderWidth: 1,\n                            borderCapStyle: 'butt',\n                            borderJoinStyle: 'miter'\n                        }\n                    },\n                    elements: {\n                        line: {\n                            tension: 0.4,\n                            borderWidth: 1,\n                            borderCapStyle: 'butt',\n                            borderJoinStyle: 'miter'\n                        },\n                        point: {\n                            radius: 4,\n                            hoverRadius: 6,\n                            hitRadius: 16\n                        }\n                    }\n                }\n            });\n            \n            // 显示图表并隐藏加载提示\n            document.getElementById('chartPlaceholder').style.display = 'none';\n            document.getElementById('performanceChart').style.display = 'block';\n            \n            return chart;\n        }\n        \n        // 初始化日志容器\n        function initLogContainer() {\n            const logContainer = document.getElementById('logContainer');\n            return logContainer;\n        }\n        \n        const buildLogKey=log=>`${log.timestamp||''}|${log.level||''}|${log.message||''}`;\n        function createLogNode(log){\n            const node=document.createElement('div');\n            node.className='log-entry';\n            const ts=log.timestamp||new Date().toISOString();\n            const level=log.level||'INFO';\n            const message=log.message||'';\n            node.dataset.logKey=buildLogKey({timestamp:ts,level,message});\n            node.innerHTML=`\n                <span class=\"timestamp\">${ts}</span>\n                <span class=\"level ${level}\">${level}</span>\n                <span class=\"message\">${message}</span>\n            `;\n            return node;\n        }\n        function trimLogOverflow(container){\n            if(!LOG_LIMIT)return;\n            while(container.children.length>LOG_LIMIT){\n                const target=container.firstChild;\n                if(!target)break;\n                if(target.dataset&&target.dataset.logKey){LOG_KEY_SET.delete(target.dataset.logKey);}\n                container.removeChild(target);\n            }\n        }\n        function appendLogBatch(container, logs, autoScroll=true){\n            try{\n                if(!Array.isArray(logs)||!logs.length)return;\n                const frag=document.createDocumentFragment();\n                let added=0;\n                logs.forEach(item=>{\n                    if(!item)return;\n                    const key=buildLogKey(item);\n                    if(LOG_KEY_SET.has(key))return;\n                    LOG_KEY_SET.add(key);\n                    frag.appendChild(createLogNode(item));\n                    added++;\n                });\n                if(!added)return;\n                container.appendChild(frag);\n                trimLogOverflow(container);\n                if(autoScroll)container.scrollTop=container.scrollHeight;\n            }catch(error){console.error('Error appending logs:',error);}\n        }\n        function prependLogBatch(container, logs){\n            try{\n                if(!Array.isArray(logs)||!logs.length)return;\n                const frag=document.createDocumentFragment();\n                let added=0;\n                logs.forEach(item=>{\n                    if(!item)return;\n                    const key=buildLogKey(item);\n                    if(LOG_KEY_SET.has(key))return;\n                    LOG_KEY_SET.add(key);\n                    frag.appendChild(createLogNode(item));\n                    added++;\n                });\n                if(!added)return;\n                const prev=container.scrollHeight;\n                container.insertBefore(frag, container.firstChild);\n                trimLogOverflow(container);\n                container.scrollTop += container.scrollHeight - prev;\n            }catch(error){console.error('Error prepending logs:',error);}\n        }\n        function addLogEntry(logContainer, logEntry){\n            appendLogBatch(logContainer,[logEntry],true);\n        }\n        function updateLoadMoreButton(){\n            if(!loadMoreLogsBtn)return;\n            const disabled=!logPagination.hasMore||LOG_LIMIT||logPagination.loading;\n            loadMoreLogsBtn.disabled=disabled;\n            loadMoreLogsBtn.textContent=disabled?'已加载全部日志':'加载更多历史';\n        }\n        function fetchLogs({loadOlder=false,silent=false}={}){\n            if(!logContainerRef)return Promise.resolve();\n            if(LOG_LIMIT){updateLoadMoreButton();return Promise.resolve();}\n            if(loadOlder&&(logPagination.nextCursor===null||!logPagination.hasMore))return Promise.resolve();\n            if(logPagination.loading)return Promise.resolve();\n            logPagination.loading=true;\n            updateLoadMoreButton();\n            const params=new URLSearchParams();\n            params.set('limit',LOG_PAGE_SIZE);\n            if(loadOlder&&logPagination.nextCursor!==null){params.set('cursor',logPagination.nextCursor);}\n            return fetch(`${API_BASE}/api/logs?${params.toString()}`,{\n                method:'GET',\n                headers:{\n                    'Content-Type':'application/json',\n                    'Cache-Control':'no-cache, no-store, must-revalidate',\n                    'Pragma':'no-cache',\n                    'Expires':'0'\n                },\n                cache:'no-store'\n            })\n                .then(r=>r.json())\n                .then(payload=>{\n                    const logs=Array.isArray(payload)?payload:(payload.logs||[]);\n                    if(loadOlder){prependLogBatch(logContainerRef,logs);}else{appendLogBatch(logContainerRef,logs,!silent);}\n                    if(!Array.isArray(payload)){\n                        logPagination.nextCursor=payload.next_cursor;\n                        logPagination.hasMore=payload.has_more;\n                    }else{\n                        logPagination.nextCursor=null;\n                        logPagination.hasMore=false;\n                    }\n                    updateLoadMoreButton();\n                })\n                .catch(err=>console.error('Failed to load logs:',err))\n                .finally(()=>{\n                    logPagination.loading=false;\n                    updateLoadMoreButton();\n                });\n        }\n        \n        function sliceRecentChartPoints(data) {\n            const liveByModel = {};\n            const timeSet = {};\n            for (const [name, points] of Object.entries(data || {})) {\n                if (!Array.isArray(points)) {\n                    liveByModel[name] = points;\n                    continue;\n                }\n                liveByModel[name] = points;\n                points.forEach(function(point) {\n                    if (point && point.time) timeSet[chartTimeKey(point.time)] = true;\n                });\n            }\n            const allTimes = Object.keys(timeSet).sort();\n            const recentTimes = allTimes.length > RECENT_CHART_POINTS\n                ? allTimes.slice(-RECENT_CHART_POINTS)\n                : allTimes;\n            const recentSet = {};\n            recentTimes.forEach(function(t) { recentSet[t] = true; });\n            const result = {};\n            for (const [name, points] of Object.entries(liveByModel)) {\n                if (!Array.isArray(points)) {\n                    result[name] = points;\n                    continue;\n                }\n                result[name] = points.filter(function(point) {\n                    return point && recentSet[chartTimeKey(point.time)];\n                });\n            }\n            return result;\n        }\n\n        function applyPerformanceChart(targetChart, data) {\n            if (!targetChart || !data) return;\n            lastPerformanceData = mergePerformanceData(lastPerformanceData, data);\n            const live = filterLiveChartData(lastPerformanceData);\n            const display = showFullData ? live : sliceRecentChartPoints(live);\n            updatePerformanceChart(targetChart, display);\n        }\n\n        function redrawPerformanceChart() {\n            if (chart && lastPerformanceData) {\n                const live = filterLiveChartData(lastPerformanceData);\n                const display = showFullData ? live : sliceRecentChartPoints(live);\n                updatePerformanceChart(chart, display);\n            }\n        }\n\n        // 更新性能图表\n        function updatePerformanceChart(chart, data) {\n            if (!chart || !data) return;\n            \n            // 清空现有数据\n            chart.data.labels = [];\n            chart.data.datasets = [];\n            \n            // 为每个模型创建数据集\n            const colors = [\n                'rgb(255, 99, 132)',\n                'rgb(54, 162, 235)',\n                'rgb(255, 205, 86)',\n                'rgb(75, 192, 192)',\n                'rgb(153, 102, 255)',\n                'rgb(255, 159, 64)'\n            ];\n            \n            let colorIndex = 0;\n            let allTimes = [];\n            \n            // 收集所有时间点\n            for (const [modelName, modelData] of Object.entries(data)) {\n                if (modelData && Array.isArray(modelData)) {\n                    modelData.forEach(point => {\n                        if (point.time && !allTimes.includes(point.time)) {\n                            allTimes.push(point.time);\n                        }\n                    });\n                }\n            }\n            \n            // 按时间排序\n            allTimes.sort();\n            \n            // 提取时间标签（只显示时间部分）\n            const timeLabels = allTimes.map(timeStr => {\n                const date = new Date(timeStr);\n                return date.toLocaleTimeString();\n            });\n            \n            chart.data.labels = timeLabels;\n            \n            // 为每个模型创建数据集\n            for (const [modelName, modelData] of Object.entries(data)) {\n                if (modelData && Array.isArray(modelData)) {\n                    const color = colors[colorIndex % colors.length];\n                    colorIndex++;\n                    \n                    // 创建与时间标签对齐的收益率数据\n                    const profits = [];\n                    const timeMap = {};\n                    \n                    // 建立时间到收益率的映射\n                    modelData.forEach(point => {\n                        timeMap[point.time] = point.profit;\n                    });\n                    \n                    // 根据时间标签填充收益率数据\n                    allTimes.forEach(timeStr => {\n                        const profitValue = timeMap[timeStr];\n                        if (profitValue !== undefined) {\n                            const numValue = typeof profitValue === 'string' ? parseFloat(profitValue) : Number(profitValue);\n                            profits.push(isNaN(numValue) ? null : numValue);\n                        } else {\n                            profits.push(null);\n                        }\n                    });\n                    \n                    const style = syncChartElementStyle(chart);\n                    const dataset = {\n                        label: modelName,\n                        data: profits,\n                        borderColor: color,\n                        backgroundColor: color.replace(')', ', 0.1)').replace('rgb', 'rgba'),\n                        fill: false,\n                        tension: style.tension,\n                        borderWidth: 1,\n                        borderCapStyle: 'butt',\n                        borderJoinStyle: 'miter',\n                        pointRadius: style.pointRadius,\n                        radius: style.pointRadius,\n                        pointHoverRadius: style.pointHoverRadius,\n                        pointHitRadius: style.pointHitRadius\n                    };\n                    \n                    chart.data.datasets.push(dataset);\n                }\n            }\n            \n            // 强制更新图表\n            chart.update('active');\n        }\n        \n        // HTTP轮询获取数据（GitHub Pages 的主要数据获取方式）\n        function fetchPerformanceData() {\n            // 如果 Socket.IO 可用，跳过 HTTP 轮询（由 Socket.IO 推送）\n            if (useSocketIO && socket && socket.connected) {\n                return;\n            }\n            \n            const url = `${API_BASE}/api/performance_full`;\n            fetch(url, {\n                method: 'GET',\n                headers: {\n                    'Content-Type': 'application/json',\n                    'Cache-Control': 'no-cache, no-store, must-revalidate',\n                    'Pragma': 'no-cache',\n                    'Expires': '0'\n                },\n                cache: 'no-store'\n            })\n                .then(response => {\n                    if (!response.ok) {\n                        throw new Error(`HTTP ${response.status}`);\n                    }\n                    return response.json();\n                })\n                .then(data => {\n                    if (chart) {\n                        applyPerformanceChart(chart, data);\n                    }\n                })\n                .catch(error => {\n                    console.error('❌ 获取性能数据失败:', error.message);\n                });\n        }\n        \n        // 注册 Service Worker\n        if ('serviceWorker' in navigator) {\n            window.addEventListener('load', function() {\n                navigator.serviceWorker.register('./sw.js')\n                    .then(function(registration) {\n                        console.log('✅ Service Worker 注册成功:', registration.scope);\n                        // 检查是否有更新\n                        registration.addEventListener('updatefound', () => {\n                            const newWorker = registration.installing;\n                            newWorker.addEventListener('statechange', () => {\n                                if (newWorker.state === 'installed' && navigator.serviceWorker.controller) {\n                                    console.log('🔄 发现 Service Worker 更新，将在刷新后生效');\n                                }\n                            });\n                        });\n                    })\n                    .catch(function(error) {\n                        console.warn('⚠️ Service Worker 注册失败:', error);\n                    });\n                \n                // 监听 Service Worker 控制权变更\n                let refreshing = false;\n                navigator.serviceWorker.addEventListener('controllerchange', () => {\n                    if (!refreshing) {\n                        refreshing = true;\n                        console.log('🔄 Service Worker 已更新，刷新页面...');\n                        // 可选：自动刷新页面以使用新的 Service Worker\n                        // window.location.reload();\n                    }\n                });\n            });\n        }\n        \n        // 启动初始化过程\n        document.addEventListener('DOMContentLoaded', function() {\n            // 初始化图表\n            const chartInitInterval = setInterval(() => {\n                const newChart = initChart();\n                if (newChart) {\n                    chart = newChart;\n                    clearInterval(chartInitInterval);\n                    console.log('图表初始化完成');\n                    // 初始化后立即获取一次数据\n                    fetchPerformanceData();\n                    // 开始定时轮询（每10秒）\n                    // 注意：如果 Socket.IO 连接成功，HTTP 轮询会被跳过\n                    setInterval(fetchPerformanceData, 10000);\n                }\n            }, 1000);\n            \n            // 添加切换显示数据的按钮事件监听器\n            const toggleButton = document.getElementById('toggleDataButton');\n            if (toggleButton) {\n                toggleButton.addEventListener('click', function() {\n                    showFullData = !showFullData;\n                    toggleButton.textContent = showFullData ? '显示最近数据' : '显示全部数据';\n                    if (lastPerformanceData) {\n                        redrawPerformanceChart();\n                    } else {\n                        fetchPerformanceData();\n                    }\n                });\n            }\n            \n            // 初始化日志容器\n            const logContainer = initLogContainer();\n            logContainerRef=logContainer;\n            loadMoreLogsBtn=document.getElementById('loadMoreLogsBtn');\n            if(loadMoreLogsBtn){loadMoreLogsBtn.addEventListener('click',()=>fetchLogs({loadOlder:true}));}\n            updateLoadMoreButton();\n            \n            // Socket.IO 事件监听已在上面初始化时设置，这里不需要重复设置\n            // 但我们可以添加一些额外的监听器用于调试\n            if (socket) {\n                // 如果连接成功，等待图表初始化后获取一次初始数据\n                socket.on('connect', function() {\n                    const waitForChart = setInterval(() => {\n                        if (chart) {\n                            clearInterval(waitForChart);\n                            // Socket.IO 连接成功时，初始数据会通过 performance_update 事件推送\n                            // 但为了确保，我们也主动获取一次\n                            if (!useSocketIO) {\n                                fetchPerformanceData();\n                            }\n                        }\n                    }, 100);\n                    setTimeout(() => clearInterval(waitForChart), 5000);\n                });\n            }\n            \n            // 页面加载时获取初始日志（完全实时，不缓存）\n            let lastLogPollTime = Date.now();\n            window.onload = function() {\n                fetchLogs().then(()=>{lastLogPollTime=Date.now();}).catch(()=>{});\n            };\n            \n            // 备用轮询机制：每5秒检查一次是否有新日志（如果SocketIO断开）\n            setInterval(function() {\n                // 如果SocketIO断开超过5秒，启用轮询\n                const timeSinceLastLog = Date.now() - lastLogPollTime;\n                if (socket && !socket.connected && timeSinceLastLog > 5000) {\n                    fetchLogs({silent:true}).then(()=>{lastLogPollTime=Date.now();}).catch(()=>{});\n                }\n            }, 5000); // 每5秒检查一次\n        });\n    </script>\n</body>\n</html>\n"
