        font-size: 14px;\n        }\n        thead {\n            background: #161b22;\n            position: sticky;\n            top: 0;\n            z-index: 10;\n        }\n        th {\n            padding: 12px 15px;\n            text-align: left;\n            font-weight: 600;\n            color: #f0f6fc;\n            border-bottom: 2px solid #21262d;\n        }\n        td {\n            padding: 12px 15px;\n            border-bottom: 1px solid #21262d;\n            color: #c9d1d9;\n        }\n        tbody tr:hover {\n            background: #1c2128;\n        }\n        .badge {\n            display: inline-block;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            font-weight: 600;\n        }\n        .text-right .badge {\n            float: right;\n        }\n        .badge.buy {\n            background: #1f6f3a;\n            color: #7ee787;\n        }\n        .badge.sell {\n            background: #801f2f;\n            color: #ff7b72;\n        }\n        .badge.profit {\n            background: #1f6f3a;\n            color: #7ee787;\n        }\n        .badge.loss {\n            background: #801f2f;\n            color: #ff7b72;\n        }\n        .text-right {\n            text-align: right;\n        }\n        .text-center {\n            text-align: center;\n        }\n        .loading {\n            text-align: center;\n            padding: 40px;\n            color: #8b949e;\n        }\n        .error {\n            background: #801f2f;\n            color: #ff7b72;\n            padding: 15px;\n            border-radius: 4px;\n            margin: 20px;\n        }\n        .empty {\n            text-align: center;\n            padding: 40px;\n            color: #8b949e;\n        }\n        .stats-grid {\n            display: grid;\n            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));\n            gap: 20px;\n            margin-bottom: 30px;\n        }\n        .stat-card {\n            background: #161b22;\n            padding: 20px;\n            border-radius: 8px;\n            border: 1px solid #21262d;\n        }\n        .stat-card .label {\n            font-size: 12px;\n            color: #8b949e;\n            margin-bottom: 8px;\n        }\n        .stat-card .value {\n            font-size: 24px;\n            font-weight: 600;\n            color: #f0f6fc;\n        }\n    </style>\n</head>\n<body>\n    <div class=\"header\">\n        <h1>Ai投资组合</h1>\n        <div class=\"header-nav\">\n            <a href=\"history.html\">日级历史收益率</a>\n            <a href=\"index.html\">实时收益及Ai决策日志</a>\n            <a href=\"portfolio.html\" class=\"active\">Ai投资组合</a>\n        </div>\n    </div>\n\n    <div class=\"container\">\n    <div class=\"filters\">\n        <div class=\"filter-group\">\n                <label>模型：</label>\n            <select id=\"modelFilter\">\n                    <option value=\"\">全部模型</option>\n            </select>\n        </div>\n        <div class=\"filter-group\">\n                <label>股票代码：</label>\n                <input type=\"text\" id=\"symbolFilter\" placeholder=\"如：000001\">\n            </div>\n            <div class=\"filter-group\">\n                <label>开始日期：</label>\n            <input type=\"date\" id=\"startDate\">\n        </div>\n        <div class=\"filter-group\">\n                <label>结束日期：</label>\n            <input type=\"date\" id=\"endDate\">\n        </div>\n        <div class=\"filter-group\">\n                <button onclick=\"loadData()\">查询</button>\n                <button onclick=\"resetFilters()\">重置</button>\n            </div>\n        </div>\n        \n        <div class=\"stats-grid\" id=\"statsGrid\"></div>\n        \n        <div class=\"section\">\n            <div class=\"section-header\">\n                <h2>持仓历史</h2>\n            </div>\n            <div class=\"table-container\">\n                <table id=\"positionsTable\">\n                    <thead>\n                        <tr>\n                            <th>模型</th>\n                            <th>股票代码</th>\n                            <th>持仓数量</th>\n                            <th>平均成本</th>\n                            <th>当前价格</th>\n                            <th class=\"text-right\">持仓市值</th>\n                            <th class=\"text-right\">盈亏金额</th>\n                            <th class=\"text-right\">盈亏比例</th>\n                        </tr>\n                    </thead>\n                    <tbody id=\"positionsBody\">\n                        <tr>\n                            <td colspan=\"8\" class=\"loading\">正在加载数据...</td>\n                        </tr>\n                    </tbody>\n                </table>\n            </div>\n        </div>\n        \n        <div class=\"section\">\n            <div class=\"section-header\">\n                <h2>交易历史</h2>\n            </div>\n            <div class=\"table-container\">\n                <table id=\"tradesTable\">\n                    <thead>\n                        <tr>\n                            <th>时间</th>\n                            <th>模型</th>\n                            <th>股票代码</th>\n                            <th>操作</th>\n                            <th class=\"text-right\">数量</th>\n                            <th class=\"text-right\">价格</th>\n                            <th class=\"text-right\">成交金额</th>\n                            <th class=\"text-right\">手续费</th>\n                            <th>置信度</th>\n                            <th>投资风格</th>\n                        </tr>\n                    </thead>\n                    <tbody id=\"tradesBody\">\n                        <tr>\n                            <td colspan=\"10\" class=\"loading\">正在加载数据...</td>\n                        </tr>\n                    </tbody>\n                </table>\n            </div>\n        </div>\n    </div>\n\n    <script>\n        // 从配置获取 API 地址\n        const API_BASE = window.API_CONFIG ? window.API_CONFIG.baseUrl : 'http://localhost:4000';\n        \n        // Socket.IO 服务器地址\n        let SOCKET_URL = API_BASE;\n        if (!SOCKET_URL.startsWith('http')) {\n            SOCKET_URL = `http://${SOCKET_URL}`;\n        }\n        \n        let models = [];\n        let socket = null;\n        let useSocketIO = false;\n        let refreshInterval = null;\n        \n        // 初始化SocketIO连接\n        function initSocketIO() {\n            try {\n                if (typeof io !== 'undefined') {\n                    socket = io(SOCKET_URL, {\n                        reconnection: true,\n                        transports: ['websocket', 'polling']\n                    });\n                    \n                    socket.on('connect', function() {\n                        useSocketIO = true;\n                        console.log('✅ SocketIO连接成功，portfolio数据将实时推送');\n                        // SocketIO连接成功后，清除定时刷新\n                        if (refreshInterval) {\n                            clearInterval(refreshInterval);\n                            refreshInterval = null;\n                        }\n                    });\n                    \n                    socket.on('disconnect', function() {\n                        useSocketIO = false;\n                        console.log('⚠️ SocketIO连接断开，将使用定时刷新');\n                        // SocketIO断开后，启用定时刷新\n                        if (!refreshInterval) {\n                            refreshInterval = setInterval(function() {\n                                loadData();\n                            }, 3600000); // 3600秒 = 1小时\n                            console.log('📊 启用定时刷新：每3600秒（1小时）刷新一次');\n                        }\n                    });\n                    \n                    socket.on('connect_error', function(error) {\n                        useSocketIO = false;\n                        console.warn('⚠️ SocketIO连接失败，将使用定时刷新:', error);\n                        // 连接失败后，启用定时刷新\n                        if (!refreshInterval) {\n                            refreshInterval = setInterval(function() {\n                                loadData();\n                            }, 3600000); // 3600秒 = 1小时\n                            console.log('📊 启用定时刷新：每3600秒（1小时）刷新一次');\n                        }\n                    });\n                    \n                    // 监听portfolio更新事件\n                    socket.on('portfolio_update', function(data) {\n                        console.log('📊 收到portfolio更新推送:', data);\n                        // 自动刷新数据\n                        loadData();\n                    });\n                } else {\n                    console.warn('⚠️ SocketIO库未加载，将使用定时刷新');\n                }\n            } catch (e) {\n                console.warn('⚠️ SocketIO初始化失败，将使用定时刷新:', e);\n            }\n        }\n        \n        // 初始化：加载模型列表\n        async function init() {\n            // 初始化SocketIO连接\n            initSocketIO();\n            \n            await loadModels();\n            await loadData();\n            \n            // 如果SocketIO不可用，启用定时刷新（每3600秒）\n            if (!useSocketIO && !refreshInterval) {\n                refreshInterval = setInterval(function() {\n                    loadData();\n                }, 3600000); // 3600秒 = 1小时\n                console.log('📊 启用定时刷新：每3600秒（1小时）刷新一次');\n            }\n        }\n        \n        async function loadModels() {\n            try {\n                // 先尝试从缓存获取模型列表\n                if (window.CacheHelper) {\n                    const cachedModels = window.CacheHelper.get('models');\n                    if (cachedModels && Array.isArray(cachedModels) && cachedModels.length > 0) {\n                        models = cachedModels;\n                        const select = document.getElementById('modelFilter');\n                        select.innerHTML = '<option value=\"\">全部模型</option>';\n                        models.forEach(modelName => {\n                            const option = document.createElement('option');\n                            option.value = modelName;\n                            option.textContent = modelName;\n                            select.appendChild(option);\n                        });\n                        // 使用缓存的数据，仍然在后台更新\n                    }\n                }\n                \n                const response = await fetch(`${API_BASE}/api/models`, { mode: 'cors' });\n                const result = await response.json();\n                if (result.status === 'success' && result.data.length > 0) {\n                    models = result.data.map(m => m.name);\n                    \n                    // 缓存模型列表（1小时）\n                    if (window.CacheHelper) {\n                        window.CacheHelper.set('models', models, window.CacheHelper.CACHE_EXPIRY.models);\n                    }\n                    \n                    const select = document.getElementById('modelFilter');\n                    select.innerHTML = '<option value=\"\">全部模型</option>';\n                    models.forEach(modelName => {\n                        const option = document.createElement('option');\n                        option.value = modelName;\n                        option.textContent = modelName;\n                        select.appendChild(option);\n                    });\n                }\n            } catch (error) {\n                console.error('加载模型列表失败:', error);\n            }\n        }\n        \n        async function loadData() {\n            const model = document.getElementById('modelFilter').value;\n            const symbol = document.getElementById('symbolFilter').value;\n            const startDate = document.getElementById('startDate').value;\n            const endDate = document.getElementById('endDate').value;\n            \n            // 加载统计数据\n            await loadStatistics(model);\n            \n            // 加载持仓\n            await loadPositions(model);\n            \n            // 加载交易历史\n            await loadTrades(model, symbol, startDate, endDate);\n        }\n        \n        async function loadStatistics(model) {\n            try {\n                const cacheKey = `statistics_${model || 'all'}`;\n                \n                // 先尝试从缓存获取统计数据\n                if (window.CacheHelper) {\n                    const cachedStats = window.CacheHelper.get(cacheKey);\n                    if (cachedStats) {\n                        const stats = cachedStats;\n                        const statsGrid = document.getElementById('statsGrid');\n                        statsGrid.innerHTML = `\n                            <div class=\"stat-card\">\n                                <div class=\"label\">总交易次数</div>\n                                <div class=\"value\">${stats.total_trades || 0}</div>\n                            </div>\n                            <div class=\"stat-card\">\n                                <div class=\"label\">买入次数</div>\n                                <div class=\"value\">${stats.buy_trades || 0}</div>\n                            </div>\n                            <div class=\"stat-card\">\n                                <div class=\"label\">卖出次数</div>\n                                <div class=\"value\">${stats.sell_trades || 0}</div>\n                            </div>\n                            <div class=\"stat-card\">\n                                <div class=\"label\">总成交量</div>\n                                <div class=\"value\">${formatNumber(stats.total_volume || 0)}</div>\n                            </div>\n                            <div class=\"stat-card\">\n                                <div class=\"label\">总成交额</div>\n                                <div class=\"value\">${formatCurrency(stats.total_value || 0)}</div>\n                            </div>\n                        `;\n                        // 使用缓存数据，仍然在后台更新\n                    }\n                }\n                \n                const url = `${API_BASE}/api/trade_statistics${model ? '?model_name=' + encodeURIComponent(model) : ''}`;\n                const response = await fetch(url, { mode: 'cors' });\n                const result = await response.json();\n                \n                if (result.status === 'success' && result.data) {\n                    const stats = result.data;\n                    \n                    // 缓存统计数据（5分钟）\n                    if (window.CacheHelper) {\n                        window.CacheHelper.set(cacheKey, stats, 5 * 60 * 1000);\n                    }\n                    \n                    const statsGrid = document.getElementById('statsGrid');\n                    statsGrid.innerHTML = `\n                        <div class=\"stat-card\">\n                            <div class=\"label\">总交易次数</div>\n                            <div class=\"value\">${stats.total_trades || 0}</div>\n                        </div>\n                        <div class=\"stat-card\">\n                            <div class=\"label\">买入次数</div>\n                            <div class=\"value\">${stats.buy_trades || 0}</div>\n                        </div>\n                        <div class=\"stat-card\">\n                            <div class=\"label\">卖出次数</div>\n                            <div class=\"value\">${stats.sell_trades || 0}</div>\n                        </div>\n                        <div class=\"stat-card\">\n                            <div class=\"label\">总成交量</div>\n                            <div class=\"value\">${formatNumber(stats.total_volume || 0)}</div>\n                        </div>\n                        <div class=\"stat-card\">\n                            <div class=\"label\">总成交额</div>\n                            <div class=\"value\">${formatCurrency(stats.total_value || 0)}</div>\n                        </div>\n                    `;\n                }\n            } catch (error) {\n                console.error('加载统计数据失败:', error);\n            }\n        }\n        \n        async function loadPositions(model) {\n            const body = document.getElementById('positionsBody');\n            body.innerHTML = '<tr><td colspan=\"8\" class=\"loading\">正在加载...</td></tr>';\n            \n            try {\n                const url = `${API_BASE}/api/current_positions${model ? '?model_name=' + encodeURIComponent(model) : ''}`;\n                const response = await fetch(url, { mode: 'cors' });\n                const result = await response.json();\n                \n                if (result.status === 'success') {\n                    if (result.data.length === 0) {\n                        body.innerHTML = '<tr><td colspan=\"8\" class=\"empty\">暂无持仓数据</td></tr>';\n                        return;\n                    }\n                    \n                    body.innerHTML = result.data.map(pos => `\n                        <tr>\n                            <td>${pos.model_name}</td>\n                            <td>${pos.symbol}</td>\n                            <td>${formatNumber(pos.quantity)}</td>\n                            <td>${formatCurrency(pos.avg_price)}</td>\n                            <td>${formatCurrency(pos.current_price)}</td>\n                            <td class=\"text-right\">${formatCurrency(pos.market_value)}</td>\n                            <td class=\"text-right\">\n                                <span class=\"${pos.profit_loss >= 0 ? 'badge profit' : 'badge loss'}\">\n                                    ${formatCurrency(pos.profit_loss)}\n                                </span>\n                            </td>\n                            <td class=\"text-right\">\n                                <span class=\"${pos.profit_loss_pct >= 0 ? 'badge profit' : 'badge loss'}\">\n                                    ${pos.profit_loss_pct.toFixed(2)}%\n                                </span>\n                            </td>\n                        </tr>\n                    `).join('');\n                } else {\n                    body.innerHTML = `<tr><td colspan=\"8\" class=\"error\">${result.message}</td></tr>`;\n                }\n            } catch (error) {\n                body.innerHTML = `<tr><td colspan=\"8\" class=\"error\">加载失败: ${error.message}</td></tr>`;\n            }\n        }\n        \n        async function loadTrades(model, symbol, startDate, endDate) {\n            const body = document.getElementById('tradesBody');\n            body.innerHTML = '<tr><td colspan=\"10\" class=\"loading\">正在加载...</td></tr>';\n            \n            try {\n                const params = new URLSearchParams();\n                if (model) params.append('model_name', model);\n                if (symbol) params.append('symbol', symbol);\n                if (startDate) params.append('start_date', startDate);\n                if (endDate) params.append('end_date', endDate);\n                params.append('limit', '1000');\n                \n                const response = await fetch(`${API_BASE}/api/trade_history?${params}`, { mode: 'cors' });\n                const result = await response.json();\n                \n                if (result.status === 'success') {\n                    if (result.data.length === 0) {\n                        body.innerHTML = '<tr><td colspan=\"10\" class=\"empty\">暂无交易记录</td></tr>';\n                        return;\n                    }\n                    \n                    body.innerHTML = result.data.map(trade => {\n                        const timestamp = new Date(trade.timestamp);\n                        return `\n                            <tr>\n                                <td>${timestamp.toLocaleString('zh-CN')}</td>\n                                <td>${trade.model_name}</td>\n                                <td>${trade.symbol}</td>\n                                <td><span class=\"badge ${trade.action === 'BUY' ? 'buy' : 'sell'}\">${trade.action === 'BUY' ? '买入' : '卖出'}</span></td>\n                                <td class=\"text-right\">${formatNumber(trade.amount)}</td>\n                                <td class=\"text-right\">${formatCurrency(trade.price)}</td>\n                                <td class=\"text-right\">${formatCurrency(trade.total_value || trade.price * trade.amount)}</td>\n                                <td class=\"text-right\">${formatCurrency(trade.commission || 0)}</td>\n                                <td>${trade.confidence ? (trade.confidence * 100).toFixed(2) + '%' : '-'}</td>\n                                <td>${trade.investment_style || '-'}</td>\n                            </tr>\n                        `;\n                    }).join('');\n                } else {\n                    body.innerHTML = `<tr><td colspan=\"10\" class=\"error\">${result.message}</td></tr>`;\n                }\n            } catch (error) {\n                body.innerHTML = `<tr><td colspan=\"10\" class=\"error\">加载失败: ${error.message}</td></tr>`;\n            }\n        }\n        \n        function resetFilters() {\n            document.getElementById('modelFilter').value = '';\n            document.getElementById('symbolFilter').value = '';\n            document.getElementById('startDate').value = '';\n            document.getElementById('endDate').value = '';\n            loadData();\n        }\n        \n        function formatCurrency(value) {\n            if (value === null || value === undefined) return '¥0.00';\n            return '¥' + parseFloat(value).toLocaleString('zh-CN', {\n                minimumFractionDigits: 2,\n                maximumFractionDigits: 2\n            });\n        }\n        \n        function formatNumber(value) {\n            if (value === null || value === undefined) return '0';\n            return parseFloat(value).toLocaleString('zh-CN');\n        }\n        \n        // 注册 Service Worker\n        if ('serviceWorker' in navigator) {\n            window.addEventListener('load', function() {\n                navigator.serviceWorker.register('./sw.js')\n                    .then(function(registration) {\n                        console.log('✅ Service Worker 注册成功:', registration.scope);\n                        // 检查是否有更新\n                        registration.addEventListener('updatefound', () => {\n                            const newWorker = registration.installing;\n                            newWorker.addEventListener('statechange', () => {\n                                if (newWorker.state === 'installed' && navigator.serviceWorker.controller) {\n                                    console.log('🔄 发现 Service Worker 更新，将在刷新后生效');\n                                }\n                            });\n                        });\n                    })\n                    .catch(function(error) {\n                        console.warn('⚠️ Service Worker 注册失败:', error);\n                    });\n                \n                // 监听 Service Worker 控制权变更\n                let refreshing = false;\n                navigator.serviceWorker.addEventListener('controllerchange', () => {\n                    if (!refreshing) {\n                        refreshing = true;\n                        console.log('🔄 Service Worker 已更新，刷新页面...');\n                        // 可选：自动刷新页面以使用新的 Service Worker\n                        // window.location.reload();\n                    }\n                });\n            });\n        }\n        \n        // 页面加载时初始化\n        document.addEventListener('DOMContentLoaded', init);\n    </script>\n</body>\n</html>\n"
    },
    {
      "path": "docs/js/history.js",
      "content": "const API_BASE = window.API_CONFIG ? window.API_CONFIG.baseUrl : 'http://localhost:4000';\nconst HISTORY_ENDPOINT = (window.API_CONFIG && window.API_CONFIG.endpoints && window.API_CONFIG.endpoints.performanceHistory)\n    ? window.API_CONFIG.endpoints.performanceHistory\n    : '/api/performance_history';\nconst MODELS_ENDPOINT = (window.API_CONFIG && window.API_CONFIG.endpoints && window.API_CONFIG.endpoints.models)\n    ? window.API_CONFIG.endpoints.models\n    : '/api/models';\n\nconst CHART_COLORS = ['#58a6ff', '#3fb950', '#f85149', '#d29922', '#a371f7', '#db6d28'];\n\nlet historyChart = null;\n\nfunction formatNumber(num, digits) {\n    const value = Number(num);\n    if (!Number.isFinite(value)) return '-';\n    return value.toLocaleString('zh-CN', {\n        minimumFractionDigits: digits,\n        maximumFractionDigits: digits\n    });\n}\n\nfunction formatPercent(num) {\n    const value = Number(num);\n    if (!Number.isFinite(value)) return '-';\n    const sign = value > 0 ? '+' : '';\n    return sign + value.toFixed(2) + '%';\n}\n\nasync function loadModels() {\n    const select = document.getElementById('modelFilter');\n    if (!select) return;\n    try {\n        const response = await fetch(`${API_BASE}${MODELS_ENDPOINT}`, { mode: 'cors', cache: 'no-store' });\n        if (!response.ok) throw new Error(`HTTP ${response.status}`);\n        const result = await response.json();\n        let modelList = [];\n        if (result && result.status === 'success' && Array.isArray(result.data)) {\n            modelList = result.data.map(item => (typeof item === 'string' ? item : item.name)).filter(Boolean);\n        } else if (Array.isArray(result)) {\n            modelList = result.map(item => (typeof item === 'string' ? item : item.name)).filter(Boolean);\n        }\n        const current = select.value;\n        select.innerHTML = '<option value=\"\">全部模型</option>';\n        modelList.forEach(name => {\n            const option = document.createElement('option');\n            option.value = name;\n            option.textContent = name;\n            select.appendChild(option);\n        });\n        if (current) select.value = current;\n    } catch (error) {\n        console.warn('加载模型列表失败:', error);\n    }\n}\n\nfunction setStatus(text, kind) {\n    const el = document.getElementById('historyStatus');\n    if (!el) return;\n    el.textContent = text;\n    el.className = 'status-text' + (kind ? ' ' + kind : '');\n}\n\nfunction emptyChart(message) {\n    const canvas = document.getElementById('historyChart');\n    if (!canvas || typeof Chart === 'undefined') return;\n    const ctx = canvas.getContext('2d');\n    if (historyChart) {\n        historyChart.destroy();\n        historyChart = null;\n    }\n    historyChart = new Chart(ctx, {\n        type: 'line',\n        data: { labels: [], datasets: [] },\n        options: {\n            responsive: true,\n            maintainAspectRatio: false,\n            plugins: {\n                legend: { display: false },\n                title: { display: true, text: message || '暂无历史收益数据', color: '#8b949e', font: { size: 16 } }\n            }\n        }\n    });\n}\n\nfunction renderChart(series) {\n    const canvas = document.getElementById('historyChart');\n    if (!canvas || typeof Chart === 'undefined') return;\n\n    const modelNames = Object.keys(series || {});\n    if (!modelNames.length) {\n        emptyChart('暂无历史收益数据');\n        return;\n    }\n\n    const dateSet = new Set();\n    modelNames.forEach(name => {\n        (series[name] || []).forEach(point => {\n            if (point && point.date) dateSet.add(point.date);\n        });\n    });\n    const labels = Array.from(dateSet).sort();\n    const datasets = modelNames.map((name, index) => {\n        const byDate = {};\n        (series[name] || []).forEach(point => {\n            if (point && point.date) byDate[point.date] = Number(point.profit) || 0;\n        });\n        return {\n            label: name,\n            data: labels.map(date => (Object.prototype.hasOwnProperty.call(byDate, date) ? byDate[date] : null)),\n            borderColor: CHART_COLORS[index % CHART_COLORS.length],\n            backgroundColor: CHART_COLORS[index % CHART_COLORS.length],\n            borderWidth: 2,\n            pointRadius: 4,\n            pointHoverRadius: 6,\n            spanGaps: true,\n            tension: 0.15\n        };\n    });\n\n    const ctx = canvas.getContext('2d');\n    if (historyChart) {\n        historyChart.destroy();\n    }\n    historyChart = new Chart(ctx, {\n        type: 'line',\n        data: { labels, datasets },\n        options: {\n            responsive: true,\n            maintainAspectRatio: false,\n            interaction: { mode: 'index', intersect: false },\n            plugins: {\n                legend: {\n                    display: true,\n                    position: 'top',\n                    labels: { color: '#c9d1d9', usePointStyle: true, padding: 16 }\n                },\n                title: {\n                    display: true,\n                    text: 'AI模型日级历史收益率',\n                    color: '#f0f6fc',\n                    font: { size: 18, weight: '600' },\n                    padding: { bottom: 12 }\n                },\n                tooltip: {\n                    callbacks: {\n                        label: function (context) {\n                            const value = context.parsed.y;\n                            if (value == null) return context.dataset.label + ': -';\n                            return context.dataset.label + ': ' + formatPercent(value);\n                        }\n                    }\n                }\n            },\n            scales: {\n                x: {\n                    ticks: { color: '#8b949e', maxRotation: 0, autoSkip: true, maxTicksLimit: 12 },\n                    grid: { color: '#21262d' },\n                    title: { display: true, text: '日期', color: '#8b949e' }\n                },\n                y: {\n                    ticks: {\n                        color: '#8b949e',\n                        callback: function (value) { return formatPercent(value); }\n                    },\n                    grid: { color: '#21262d' },\n                    title: { display: true, text: '累计收益率 (%)', color: '#8b949e' }\n                }\n            }\n        }\n    });\n}\n\nfunction renderSummary(series) {\n    const grid = document.getElementById('statsGrid');\n    if (!grid) return;\n    const modelNames = Object.keys(series || {});\n    if (!modelNames.length) {\n        grid.innerHTML = '';\n        return;\n    }\n    grid.innerHTML = modelNames.map(name => {\n        const points = series[name] || [];\n        const latest = points.length ? points[points.length - 1] : null;\n        const profit = latest ? latest.profit : 0;\n        const cls = profit >= 0 ? 'positive' : 'negative';\n        return `\n            <div class=\"stat-card\">\n                <div class=\"label\">${name}</div>\n                <div class=\"value ${cls}\">${formatPercent(profit)}</div>\n                <div class=\"meta\">${points.length} 个交易日${latest && latest.date ? ' · 最新 ' + latest.date : ''}</div>\n            </div>\n        `;\n    }).join('');\n}\n\nfunction renderTable(records) {\n    const body = document.getElementById('historyBody');\n    if (!body) return;\n    if (!records || !records.length) {\n        body.innerHTML = '<tr><td colspan=\"8\" class=\"empty\">暂无历史收益数据。每轮交易结束后会写入 logs/trades.db</td></tr>';\n        return;\n    }\n    const sorted = records.slice().sort((a, b) => {\n        const dateCmp = String(b.date || '').localeCompare(String(a.date || ''));\n        if (dateCmp !== 0) return dateCmp;\n        return String(a.model_name || '').localeCompare(String(b.model_name || ''));\n    });\n    body.innerHTML = sorted.map(row => {\n        const profit = Number(row.return_rate) || 0;\n        const cls = profit >= 0 ? 'positive' : 'negative';\n        return `\n            <tr>\n                <td>${row.date || '-'}</td>\n                <td>${row.model_name || '-'}</td>\n                <td class=\"text-right ${cls}\">${formatPercent(profit)}</td>\n                <td class=\"text-right\">¥${formatNumber(row.total_equity, 2)}</td>\n                <td class=\"text-right\">¥${formatNumber(row.total_profit, 2)}</td>\n                <td class=\"text-right\">${row.total_trades == null ? '-' : row.total_trades}</td>\n                <td class=\"text-right\">${row.positions_count == null ? '-' : row.positions_count}</td>\n                <td class=\"text-right\">¥${formatNumber(row.available_cash, 2)}</td>\n            </tr>\n        `;\n    }).join('');\n}\n\nasync function loadHistory() {\n    const model = (document.getElementById('modelFilter') || {}).value || '';\n    const startDate = (document.getElementById('startDate') || {}).value || '';\n    const endDate = (document.getElementById('endDate') || {}).value || '';\n    const params = new URLSearchParams();\n    if (model) params.append('model_name', model);\n    if (startDate) params.append('start_date', startDate);\n    if (endDate) params.append('end_date', endDate);\n\n    setStatus('正在加载日级历史收益...', '');\n    const body = document.getElementById('historyBody');\n    if (body) {\n        body.innerHTML = '<tr><td colspan=\"8\" class=\"loading\">正在加载数据...</td></tr>';\n    }\n\n    try {\n        const url = `${API_BASE}${HISTORY_ENDPOINT}${params.toString() ? '?' + params.toString() : ''}`;\n        const response = await fetch(url, { mode: 'cors', cache: 'no-store' });\n        if (!response.ok) throw new Error(`HTTP ${response.status}`);\n        const result = await response.json();\n        if (result && result.status === 'error') {\n            throw new Error(result.message || '接口返回错误');\n        }\n        const records = (result && result.data) || [];\n        const series = (result && result.series) || {};\n        const modelCount = Object.keys(series).length;\n        const pointCount = Object.values(series).reduce((sum, arr) => sum + (arr ? arr.length : 0), 0);\n\n        renderChart(series);\n        renderSummary(series);\n        renderTable(records);\n\n        if (!modelCount) {\n            setStatus('暂无历史数据（可先运行几轮交易）', 'warn');\n        } else {\n            setStatus(`已加载 ${modelCount} 个模型、共 ${pointCount} 个日级数据点（logs/trades.db）`, 'ok');\n        }\n    } catch (error) {\n        console.error('加载日级历史收益失败:', error);\n        emptyChart('加载失败');\n        renderSummary({});\n        if (body) {\n            body.innerHTML = `<tr><td colspan=\"8\" class=\"error\">加载失败: ${error.message}<br>请确认交易程序已启动，且 config.js 中的 API_BASE_URL 可访问</td></tr>`;\n        }\n        setStatus('加载失败: ' + error.message, 'error');\n    }\n}\n\nfunction resetFilters() {\n    const model = document.getElementById('modelFilter');\n    const startDate = document.getElementById('startDate');\n    const endDate = document.getElementById('endDate');\n    if (model) model.value = '';\n    if (startDate) startDate.value = '';\n    if (endDate) endDate.value = '';\n    loadHistory();\n}\n\nwindow.addEventListener('DOMContentLoaded', () => {\n    loadModels();\n    loadHistory();\n});\n"
