      "path": "docs/sw.js",
      "content": "// Service Worker 版本号（更新时修改此版本号以强制更新）\nconst CACHE_VERSION = 'v2.0.8';\nconst CACHE_NAME = `ai-trader-${CACHE_VERSION}`;\n\n// 需要缓存的静态资源（使用相对路径，适配 GitHub Pages）\nconst STATIC_ASSETS = [\n    './',\n    './index.html',\n    './portfolio.html',\n    './history.html',\n    './config.js',\n    './manifest.json',\n    './js/sw-helper.js',\n    './js/cache-helper.js',\n    // Chart.js 和 Socket.IO 通过 CDN 加载，不需要缓存\n];\n\n// 不需要缓存的路径（API 调用，确保实时性）\nconst NO_CACHE_PATHS = [\n    '/api/',\n    '/performance_update',\n    '/ai_log',\n    '.ts.net'  // Tailscale Funnel URL\n];\n\n// 安装 Service Worker\nself.addEventListener('install', (event) => {\n    console.log('[SW] 安装中...', CACHE_NAME);\n    \n    event.waitUntil(\n        caches.open(CACHE_NAME)\n            .then((cache) => {\n                console.log('[SW] 缓存静态资源');\n                // 缓存静态资源\n                return cache.addAll(STATIC_ASSETS.map(url => new Request(url, { cache: 'reload' })))\n                    .catch((error) => {\n                        console.warn('[SW] 部分资源缓存失败:', error);\n                        // 即使部分失败也继续\n                    });\n            })\n            .then(() => {\n                // 安装后立即激活，无需等待用户关闭所有标签页\n                return self.skipWaiting();\n            })\n    );\n});\n\n// 激活 Service Worker\nself.addEventListener('activate', (event) => {\n    console.log('[SW] 激活中...', CACHE_NAME);\n    \n    event.waitUntil(\n        caches.keys().then((cacheNames) => {\n            // 删除旧版本的缓存\n            return Promise.all(\n                cacheNames.map((cacheName) => {\n                    if (cacheName !== CACHE_NAME && cacheName.startsWith('ai-trader-')) {\n                        console.log('[SW] 删除旧缓存:', cacheName);\n                        return caches.delete(cacheName);\n                    }\n                })\n            );\n        })\n        .then(() => {\n            // 立即控制所有客户端\n            return self.clients.claim();\n        })\n    );\n});\n\n// 拦截网络请求\nself.addEventListener('fetch', (event) => {\n    const url = new URL(event.request.url);\n    \n    // 检查是否是不应该缓存的路径\n    const shouldNotCache = NO_CACHE_PATHS.some(path => url.href.includes(path));\n    \n    // API 调用：直接通过网络获取，不使用缓存\n    if (shouldNotCache) {\n        event.respondWith(\n            fetch(event.request)\n                .catch(() => {\n                    // 网络失败时，返回错误信息\n                    return new Response(\n                        JSON.stringify({ error: '网络连接失败，请检查网络' }),\n                        {\n                            status: 503,\n                            headers: { 'Content-Type': 'application/json' }\n                        }\n                    );\n                })\n        );\n        return;\n    }\n    \n    // 静态资源：使用缓存优先策略\n    event.respondWith(\n        caches.match(event.request)\n            .then((cachedResponse) => {\n                // 如果缓存中有，返回缓存\n                if (cachedResponse) {\n                    return cachedResponse;\n                }\n                \n                // 否则从网络获取\n                return fetch(event.request)\n                    .then((response) => {\n                        // 只缓存成功的 GET 请求\n                        if (response.status === 200 && event.request.method === 'GET') {\n                            const responseToCache = response.clone();\n                            caches.open(CACHE_NAME).then((cache) => {\n                                cache.put(event.request, responseToCache);\n                            });\n                        }\n                        return response;\n                    })\n                    .catch(() => {\n                        // 网络失败且无缓存时，返回离线页面\n                        if (event.request.mode === 'navigate') {\n                            return caches.match('./index.html') || caches.match('./');\n                        }\n                    });\n            })\n    );\n});\n\n// 监听消息（用于手动更新缓存）\nself.addEventListener('message', (event) => {\n    if (event.data && event.data.type === 'SKIP_WAITING') {\n        self.skipWaiting();\n    }\n    \n    if (event.data && event.data.type === 'CACHE_CLEAR') {\n        caches.delete(CACHE_NAME).then(() => {\n            event.ports[0].postMessage({ success: true });\n        });\n    }\n});\n\n"
    },
